import pandas as pd
import numpy as np

def r_bake(object, new_data=None, **kwargs):
    """
    Apply learned transformations from a recipe step to new data.

    Parameters:
    -----------
    object : dict
        A trained recipe step object containing transformation information
    new_data : pd.DataFrame
        New data to transform
    **kwargs : additional arguments
        Additional arguments passed through

    Returns:
    --------
    pd.DataFrame
        Transformed data
    """

    if new_data is None:
        raise ValueError("new_data argument is required")

    # Ensure new_data is a DataFrame
    if not isinstance(new_data, pd.DataFrame):
        new_data = pd.DataFrame(new_data)

    result = new_data.copy()

    # Handle removals (e.g., from zero variance filter or other steps)
    if isinstance(object, dict) and 'removals' in object:
        removals = object['removals']
        if removals is not None:
            if isinstance(removals, str):
                cols_to_remove = [removals]
            elif isinstance(removals, list):
                cols_to_remove = removals
            else:
                cols_to_remove = []

            for col in cols_to_remove:
                if col in result.columns:
                    result = result.drop(columns=[col])

    # Preserve integer dtypes - convert float columns that are all integers back to int
    for col in result.columns:
        if result[col].dtype == np.float64 or result[col].dtype == np.float32:
            # Check if all non-null values are actually integers
            if result[col].notna().any():
                non_null = result[col].dropna()
                if len(non_null) > 0 and np.all(non_null == non_null.astype(int)):
                    result[col] = result[col].astype('Int64')

    return result
